-- Enrich Course 2 Lesson 7 with the Standard Kurmanji direct/oblique pronoun inventory
-- and the past-transitive ergative alignment, while isolating dialect variation.
-- Haig (2018), Table 9 and §2.7.2 ex. (32); Haig & Öpengin (2018), §3.7.2.
DO $migration$
DECLARE affected integer;
BEGIN
  UPDATE public.lesson_content
  SET title = 'جێناوە کەسییەکان و حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ',
      content_html = $new$<section class="klesson-card"><h2>١. فۆڕمەکانی جێناوی کەسی</h2><p>لە کورمانجیی ستاندارددا جێناوە کەسییەکان دوو کۆمەڵەی سەرەکییان هەیە:</p><ul><li><strong>ڕاستەوخۆ:</strong> <em>ez, tu, ew, em, hûn, ew</em>.</li><li><strong>ناڕاستەوخۆ:</strong> <em>min, te, wî/wê, me, we, wan</em>.</li></ul><p><em>ew</em> بۆ سێیەمی تاک و کۆ بەکاردێت؛ لە فۆڕمی ناڕاستەوخۆدا <em>wî</em> بۆ تاکی نێر، <em>wê</em> بۆ تاکی مێ و <em>wan</em> بۆ کۆیە. بۆیە ژمارە و ڕەگەز لە سیاق و ڕستەوە دیاری دەکرێن.</p></section><section class="klesson-card"><h2>٢. حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ</h2><p>ناوی «ڕاستەوخۆ» و «ناڕاستەوخۆ» بە تەنها هاوتای «بکەر» و «بەرکار» نین؛ ئەرکی ڕێزمانی بە کات و جۆری کردارەوە پەیوەستە. لە ڕستەی ئێستا، بکەری کردارێکی تێپەڕ زۆرجار ڕاستەوخۆ و بەرکار ناڕاستەوخۆیە. بەڵام لە ڕستەی ڕابردووی کردارێکی تێپەڕدا، لە پێکهاتەی ئەرگاتیڤی ستاندارددا بکەر ناڕاستەوخۆ و بەرکار ڕاستەوخۆیە؛ کردارەکەش لەگەڵ بەرکاری ڕاستەوخۆ ڕێکدەکەوێت.</p></section><section class="klesson-card"><h2>٣. نموونەی ڕابردووی تێپەڕ</h2><p><em>Wî mirov-î çay anî.</em> «ئەو پیاوە چای هێنا.»</p><ul><li><em>wî mirov-î</em>: بکەر بە فۆڕمی ناڕاستەوخۆ.</li><li><em>çay</em>: بەرکاری ڕاستەوخۆ.</li><li><em>anî</em>: کرداری ڕابردووی تێپەڕ.</li></ul><p>ئەم نموونەیە نیشان دەدات کە بکەر هەر بکەرە، هەرچەندە فۆڕمی ناڕاستەوخۆی هەیە. لە کورمانجیی باکووردا پێویستە حاڵەت و ئەرکی ڕێزمانی لە یەکتر جیا بکرێنەوە.</p></section><section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">خشتەی جێناوەکان لە Haig (2018)، Table 9، هاتووە. بنەمای جیاوازیی حاڵەت و ڕێککەوتنی کردار لە ڕستەی تێپەڕی ڕابردوودا لە Haig (2018)، §2.7.2، و Haig & Öpengin (2018)، §3.7.2، ڕوون کراوەتەوە. هەندێک شێوەزار، وەک نموونەی تۆمارکراوی مووش، دەتوانن لە حاڵەتی بەرکاردا جیاوازییان هەبێت؛ ئەو جیاوازییە نابێت بە یاسای گشتیی کورمانجیی ستاندارد بخوێنرێتەوە.</p></section><section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>فۆڕمە ڕاستەوخۆ و ناڕاستەوخۆکانی جێناوی سێیەم چین؟</li><li>لە ڕابردووی کردارێکی تێپەڕدا بکەر و بەرکار بە چ فۆڕمێک دەردەکەون؟</li><li>لە نموونەی <em>Wî mirov-î çay anî</em>، کام بەش بکەرە و کام بەش بەرکارە؟</li><li>بۆچی نابێت «ناڕاستەوخۆ» بە مانای «بەرکار» وەربگیرێت؟</li></ol></section><section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” §2.2.3, Table 9; §2.7.2, example (32). <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Haig, Geoffrey & Ergin Öpengin. (2018). “Kurmanji Kurdish in Turkey: Structure, varieties and status.” §3.7.2. <a href="https://www.uni-bamberg.de/fileadmin/aspra/06_Team/Publications_and_CV/HaigOepengin2018_Kurmanji_Kurdish_.pdf" target="_blank" rel="noopener">PDF — University of Bamberg</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">وانەکە بنەمای کورمانجیی ستاندارد دەخاتەڕوو و جیاوازییە ناوچەییەکان بە شێوەی جیاواز نیشان دەدات.</p></section>$new$,
      updated_at = now()
  WHERE lesson_key = 'kurmanji-course-2-lesson-07.html'
    AND course_id = 'kurmanji-course-2'
    AND content_html = $old$<section class="klesson-card"><h2>١. فۆڕمەکانی جێناوی کەسی</h2><p>لە کورمانجیی ستاندارددا فۆڕمە ڕاستەوخۆکان بریتین لە ez, tu, ew, em, hûn, ew؛ فۆڕمە ناڕاستەوخۆکانیش min, te, wî/wê, me, we, wan. ئەم دوو کۆمەڵەیە لە Haig (2018)دا بە شێوەی خشتە هاتوون.</p></section><section class="klesson-card"><h2>٢. حاڵەت و ئەرکی ڕستە</h2><p>حاڵەتی ناڕاستەوخۆ لە کورمانجی‌دا لە چەند ژینگەی ڕێزمانی دەردەکەوێت؛ بۆیە نابێت بە یاسای «هەمیشە بکەر ناڕاستەوخۆیە» یان «هەمیشە بەرکار ڕاستەوخۆیە» کورت بکرێتەوە. کات، جۆری کردار و پێکهاتەی ڕستە کاریگەرییان هەیە.</p></section><section class="klesson-card"><h2>٣. سیستەمی ڕابردوو</h2><p>لە ڕستەی ڕابردووی زۆرێک لە کردارە تێپەڕەکاندا، بکەر دەتوانێت بە فۆڕمی ناڕاستەوخۆ دەربکەوێت، لە کاتێکدا بەرکار بە شێوەیەکی دیکە ڕێکدەکەوێت. ئەمە بابەتی گرنگی سیستەمی حاڵەت و ergativity ـە و پەیویستی بە شیکردنەوەی ڕستەی تەواو هەیە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">خشتەی جێناوەکان لە Haig (2018)، Table 9، و Thackston هەڵبژێردراوە. فۆڕمی ڕاستەوخۆی ew بۆ تاکی نێر، تاکی مێ و کۆ بەکاردێت و ژمارە و ڕەگەز لە سیاقەوە دەزانرێت؛ لە فۆڕمی ناڕاستەوخۆدا wî بۆ تاکی نێر، wê بۆ تاکی مێ و wan بۆ کۆیە. لە پشکنینی ڕستەی تایبەتدا کات و جۆری کردار دیاری بکە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>فۆڕمە ڕاستەوخۆ و ناڕاستەوخۆکانی ez، tu، ew چین؟</li><li>بۆچی حاڵەت تەنیا بە ئەرکی بکەر/بەرکار ناسراو ناکرێت؟</li><li>ڕابردووی کردارە تێپەڕەکان چ پەیوەندییەکیان بە حاڵەتی ناڕاستەوخۆوە هەیە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>$old$;

  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Expected exactly one unchanged Course 2 Lesson 7 row; updated % rows', affected;
  END IF;
END
$migration$;
